import{rng,mapFor,search,policy,fixed,candidates,evaluate}from'./engine.js';
const $=id=>document.getElementById(id),names={greedy:'Greedy 贪心搜索',bfs:'BFS 广度优先',astar:'A* 启发式搜索'};
let mode='rsi',cfg={...fixed},Q={},gen=0,accepted=0,running=false,busy=false,mapIndex=1,current=mapFor(900001),history=[],token=0;
const tests=Array.from({length:40},(_,i)=>mapFor(700000+i));
function config(){const c=mode==='fixed'?fixed:cfg;$('agentName').textContent={fixed:'Fixed Agent',rl:'RL Agent',rsi:'RSI Agent'}[mode];$('agentDesc').textContent={fixed:'重复执行同一套算法，不学习',rl:'根据奖励信号更新 Q 值',rsi:'评估失败，搜索更好的算法配置'}[mode];$('version').textContent=mode==='rsi'?`v1.${accepted}`:mode==='rl'?`Q · ${gen}`:'v1.0';$('algorithm').textContent=mode==='rl'?'Q-learning 局部策略':names[c.kind];$('weight').textContent=mode==='rl'?'—':c.kind==='astar'?c.weight.toFixed(2):'不适用';$('depth').textContent=mode==='rl'?'60 步行动上限':c.depth;$('config').textContent=mode==='rl'?`policy: "q-learning"\nlearning_rate: 0.18\ndiscount: 0.94\ntraining_episodes: ${gen*288}`:`strategy: "${c.kind}"\nheuristic_weight: ${c.kind==='astar'?c.weight.toFixed(2):'不适用'}\nmax_depth: ${c.depth}\ncompute_budget: 240`;$('accepted').innerHTML=`${accepted}<small>次</small>`;$('generation').textContent=`GEN ${String(gen).padStart(2,'0')}`;const v=history.at(-1)?.[mode];$('success').innerHTML=`${v?v.rate.toFixed(1):'—'}<small>%</small>`;$('average').innerHTML=`${v?.avg!=null?v.avg.toFixed(1):'—'}<small>步</small>`}
function board(path=[0]){const visited=new Set(path),p=path.at(-1);$('board').innerHTML=current.walls.map((w,i)=>`<div class="cell ${w?'wall':''} ${visited.has(i)?'visited':''} ${current.rewards.has(i)?'reward':''} ${i===99?'goal':''} ${i===p?'bot':''}">${i===p?'▣':i===99?'⚑':current.rewards.has(i)?'◆':visited.has(i)?'·':''}</div>`).join('');$('steps').textContent=path.length-1;$('mapId').textContent='#'+String(mapIndex).padStart(4,'0')}
function log(msg,good=false){let el=document.createElement('div');el.className='log'+(good?' good':'');let n=document.createElement('span');n.textContent=String(gen).padStart(2,'0');let p=document.createElement('p');p.textContent=msg;el.append(n,p);$('logs').prepend(el);while($('logs').children.length>30)$('logs').lastChild.remove()}
function chart(){let lines=[0,25,50,75,100].map(v=>`<line x1="30" x2="630" y1="${150-v*1.3}" y2="${150-v*1.3}" stroke="#edf0e8"/><text x="0" y="${154-v*1.3}" font-size="10" fill="#9aa58f">${v}</text>`).join('');for(const [key,color]of[['fixed','#b7b9a3'],['rl','#6f9dc8'],['rsi','#40825d']]){let pts=history.map((v,i)=>`${30+i*590/Math.max(10,history.length-1)},${150-v[key].rate*1.3}`).join(' ');lines+=`<polyline fill="none" stroke="${color}" stroke-width="2.5" ${key==='fixed'?'stroke-dasharray="4 4"':''} points="${pts}"/>`;if(history.length){let i=history.length-1;lines+=`<circle cx="${30+i*590/Math.max(10,i)}" cy="${150-history[i][key].rate*1.3}" r="3" fill="${color}"/>`}}for(let i=0;i<=Math.max(10,history.length-1);i+=Math.max(1,Math.ceil(history.length/10)))lines+=`<text x="${30+i*590/Math.max(10,history.length-1)}" y="174" fill="#9aa58f" font-size="10">${i}</text>`;$('chart').innerHTML=lines}
function measure(){history.push({rsi:evaluate(tests,m=>search(m,cfg)),rl:evaluate(tests,m=>policy(m,Q)),fixed:evaluate(tests,m=>search(m,fixed))});chart();config()}
function setBusy(value){busy=value;for(const id of['step','map','reset'])$(id).disabled=value;document.querySelectorAll('[data-mode]').forEach(b=>b.disabled=value)}
async function generation(){if(busy)return;setBusy(true);const own=token;$('state').textContent='正在训练与验证';await new Promise(r=>setTimeout(r,30));if(!history.length)measure();gen++;const random=rng(42+gen);for(let i=0;i<24;i++){const m=mapFor(100000+gen*24+i);for(let e=0;e<12;e++)policy(m,Q,{train:true,random,epsilon:Math.max(.08,.35/(1+gen*.08))})}const validation=Array.from({length:24},(_,i)=>mapFor(300000+gen*24+i));const old=evaluate(validation,m=>search(m,cfg));let best=old,next=cfg;for(const c of candidates){const score=evaluate(validation,m=>search(m,c));if(score.score>best.score+1e-9){best=score;next=c}}if(next!==cfg){cfg={...next};accepted++;log(`保留 v1.${accepted} · ${names[cfg.kind]}，验证成功率 ${old.rate.toFixed(0)}% → ${best.rate.toFixed(0)}%，平均步数 ${best.avg?.toFixed(1)??'—'}。`,true)}else log('候选未超过当前策略，保留原版本。改进并不必然发生。');measure();$('chartCaption').textContent=`已完成 ${gen} 代 · 测试集不参与选择 · 每代 RL 训练 288 次 / RSI 评估 ${candidates.length} 个候选`;
const result=mode==='rl'?policy(current,Q):search(current,mode==='fixed'?fixed:cfg);$('cost').textContent=`${result.cost} / 240`;$('state').textContent='正在回放路径';for(let i=1;i<=result.path.length;i++){if(own!==token)break;board(result.path.slice(0,i));await new Promise(r=>setTimeout(r,Number($('speed').value)))}$('state').textContent=result.success?'已抵达终点':'预算或深度耗尽';setBusy(false);if(running&&own===token)setTimeout(()=>{if(running&&!busy){newMap();generation()}},350)}
function newMap(){mapIndex++;current=mapFor(900000+mapIndex);board();$('cost').textContent='0 / 240';$('state').textContent='新演示地图'}
$('run').onclick=()=>{running=!running;$('run').textContent=running?'Ⅱ 暂停连跑':'▶ 继续实验';if(running&&!busy)generation()};$('step').onclick=()=>{running=false;$('run').textContent='▶ 继续实验';generation()};$('map').onclick=newMap;
$('reset').onclick=()=>{token++;running=false;gen=0;accepted=0;Q={};cfg={...fixed};history=[];mapIndex=1;current=mapFor(900001);$('logs').innerHTML='';log('实验已重置，随机种子保持 0042。');$('run').textContent='▶ 开始实验';$('state').textContent='等待开始';$('cost').textContent='0 / 240';$('chartCaption').textContent='运行实验后显示真实测量结果 · 横轴为代数';board();chart();config()};
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('active',x===b));config();board();$('cost').textContent='0 / 240';$('state').textContent='等待运行'});for(const id of['help','details'])$(id).onclick=()=>$('dialog').showModal();$('close').onclick=()=>$('dialog').close();$('dialog').onclick=e=>{if(e.target===$('dialog'))$('dialog').close()};board();chart();config();

// Render the catalogue from the actual candidate pool to keep the explanation in sync.
$('candidateRows').innerHTML=candidates.map((c,i)=>`<tr><th scope="row">${i+1}</th><td>${names[c.kind]}</td><td>${c.kind==='astar'?c.weight:'不适用'}</td><td>${c.depth} 步</td></tr>`).join('');
